"""Local new-ten drawing comparison viewer from independent saved-file checks."""
import sys,json,os,html
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parent))
from build_review_page import STYLE

def build(base):
 base=Path(base).resolve();summary=json.loads((base/'independent-summary.json').read_text(encoding='utf-8'));manifest=json.loads((base/'manifest.json').read_text(encoding='utf-8'));sources={e['id']:e for e in manifest['entries']};rows=[]
 def rel(p):return Path(os.path.relpath(p,base)).as_posix() if p and Path(p).is_file() else None
 for r in summary['rows']:
  cid=r['id'];d=base/cid;physical=Path(r['physical_dxf']) if r.get('physical_dxf') else None
  initial=base.parent/'independent-review/N01-first/page-01_deepseek_harness.png' if cid=='N01' else physical.with_suffix('.png') if physical and cid not in ['N09','N10'] else None
  original=d/'page-01.png'
  rows.append({'id':cid,'status':r['status'],'error_percent':r.get('max_relative_error',0)*100,'source':sources[cid]['url'],'initial_label':'最初模型JSON编译 · 未通过' if cid=='N01' else '内部配对修正前未留存' if cid in ['N09','N10'] else '新版工具首次处理留存','initial':rel(initial),'final':rel(physical.with_suffix('.png')) if physical else None,'original':rel(original),'pdf':rel(d/'original.pdf'),'dxf':rel(physical),'review':rel(d/'independent-review.json'),'brief':rel(d/'functional_modules.md'),'functional_dxf':rel(d/('n01-functional-labeled.dxf' if cid=='N01' else 'functional.dxf')),'functional':r.get('functional',{}),'audit':r.get('source_audit',{}),'body':r.get('front_body',{}),'dim_count':len(r.get('dimensions',[]))})
 data=json.dumps(rows,ensure_ascii=False).replace('<','\\u003c');counts=summary['counts'];passed=counts['TECHNICAL_PASS_1PCT']
 extra='''.metrics{margin:18px 0}.facts{display:flex;flex-wrap:wrap;gap:16px}.fact{padding:10px 16px;background:#edf3f8;border-radius:5px}.status p{margin:8px 0}dialog img{background:white}.toolbar button{padding:6px 15px}'''
 js=r'''
const rows=ROWS,select=document.querySelector('#sample'),tabs=document.querySelector('#samples'),out=document.querySelector('#case');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(p,l)=>p?`<a href="${esc(p)}" target="_blank" rel="noopener">${l}</a>`:'';
function media(title,url,note,links=''){return `<section class="panel"><h3>${title}</h3><div class="media">${url?`<a href="${esc(url)}" data-zoom="${esc(url)}" aria-label="放大${title}"><img src="${esc(url)}" alt="${esc(title)}"></a>`:'<div class="empty">初版未留存，不补造首轮</div>'}</div><div class="status"><p>${note}</p><div class="links">${links}</div></div></section>`}
function show(id){const r=rows.find(x=>x.id===id)||rows[0];select.value=r.id;location.replace('#'+r.id);tabs.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.id===r.id)));const pass=r.status==='TECHNICAL_PASS_1PCT';out.innerHTML=`<h2>${esc(r.id)} · 光学安装座</h2><div class="facts"><div class="fact">${pass?'技术复核通过':'待复核 / 未运行'}</div><div class="fact">已核对项最大相对误差 ${r.error_percent.toFixed(2)}%</div><div class="fact">重开核对 ${r.dim_count} 组尺寸</div></div><div class="comparison" style="margin-top:18px">${media('原件 · 公开厂家PDF',r.original,'源图保留，图示信息仅供参考，不构成制造放行。',link(r.pdf,'原始PDF')+link(r.source,'厂家来源'))}${media('初审 · '+esc(r.initial_label),r.initial,r.id==='N01'?'首例直接生成未通过，后经反馈优化工具。':r.initial?'本图首次使用已优化工具转写，首稿保留。':'N09/N10 曾在内部修正配对；修正前文件未保留，不能计为初次直接通过。')}${media('交付 · 可编辑CAD真实渲染',r.final,pass?'按用户约1%口径通过技术复核。':'N10 主轮廓自动定位未完成独立核对；已核尺寸合格，暂不计整张通过。',link(r.dxf,'可编辑DXF')+link(r.review,'独立检查JSON'))}</div><section class="detail"><h3>覆盖与仍需确认的范围</h3><p>独立从原PDF和保存后的DXF核对：源几何边 ${r.audit.source_segments??'待核'} 条，CAD几何边 ${r.audit.dxf_segments??'待核'} 条；原图文字 ${r.audit.source_text_spans??'待核'} 组，CAD文字 ${r.audit.dxf_text_spans??'待核'} 组。漏边 ${r.audit.missing_segments??'待核'}，漏字或移位 ${r.audit.missing_or_moved_text??'待核'}。这项检查包含源图中的端面、剖面、等轴及图注。</p><p>已核对图面结构与实际毫米尺度；未标注的制造细节、完整螺纹实体、公差制造放行均不作保证。源PDF的折线逼近和少量字体/标志渲染差异在报告中保留，不继续做像素级优化。</p><p>功能图：${r.functional.pass?'系统边界、四模块、三条连接和名称通过':'见功能检查详情'}。</p><div class="links">${link(r.brief,'独立功能说明')}${link(r.functional_dxf,'功能模块DXF')}${link(r.review,'尺寸、主轮廓及功能检查详情')}</div></section>`;out.querySelectorAll('[data-zoom]').forEach(a=>a.onclick=e=>{e.preventDefault();document.querySelector('#zoomimg').src=a.dataset.zoom;document.querySelector('#zoomtitle').textContent=a.getAttribute('aria-label');document.querySelector('#zoom').showModal()})}
rows.forEach(r=>{const o=document.createElement('option');o.value=r.id;o.textContent=r.id+' · '+(r.status==='TECHNICAL_PASS_1PCT'?'通过':'待核');select.append(o);const b=document.createElement('button');b.textContent=r.id;b.dataset.id=r.id;b.onclick=()=>show(r.id);tabs.append(b)});select.onchange=()=>show(select.value);document.querySelector('#closezoom').onclick=()=>document.querySelector('#zoom').close();document.querySelector('#actual').onclick=()=>{const p=document.querySelector('.zoomscroll');p.classList.toggle('actual');document.querySelector('#actual').setAttribute('aria-pressed',String(p.classList.contains('actual')))};window.addEventListener('hashchange',()=>{if(select.value!==location.hash.slice(1))show(location.hash.slice(1))});show(location.hash.slice(1));
'''
 page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CAD新十图对照</title><style>STYLE</style><header><div>DEEPSEEK HARNESS · 新十图</div><h1>原图与可编辑CAD，逐张核对</h1><p>用户验收口径：整体尺寸及轮廓约1%误差以内；漏视图、漏孔槽和连接错误单独拦截。</p><div class="metrics"><div class="metric"><strong>PASS_COUNT / 10</strong>独立技术复核通过</div><div class="metric"><strong>1%</strong>用户认可误差口径</div><div class="metric"><strong>8 / 10</strong>目标</div></div></header><main><div class="notice">方法：DeepSeek在原Harness中读取图片和功能说明、组织配对并实现工具；工具从原始矢量PDF转写可编辑实体。本批为同一厂商同一产品系列的10张不同图，不能据此宣称低清位图重建或广泛泛化能力。N01用于反馈优化；N02–N08保留新版工具首次处理稿；N09/N10在内部修正配对且早稿未留存，不能声称9/10初次直过。</div><nav class="toolbar"><label for="sample">选择图纸</label><select id="sample"></select><a href="independent-summary.json">全部独立检查</a></nav><nav class="samples" id="samples" aria-label="图纸编号"></nav><article id="case" aria-live="polite"></article><footer>当前原会话界面声明模型 DeepSeek-V4.1-Flash 1017 High；供应商原始模型回执未取得。通过表示本机技术复核，不代表代用户最终验收或可制造放行。本页仅在本地生成，未部署。</footer></main><dialog id="zoom" aria-labelledby="zoomtitle"><div class="zoomhead"><strong id="zoomtitle">图纸放大</strong><button class="secondary" id="actual" aria-pressed="false">切换原始像素</button><button class="secondary" id="closezoom">关闭</button></div><div class="zoomscroll"><img id="zoomimg" alt="放大图纸"></div></dialog><script>JS</script></html>'''
 page=page.replace('STYLE',STYLE+extra).replace('PASS_COUNT',str(passed)).replace('JS',js.replace('ROWS',data))
 (base/'index.html').write_text(page,encoding='utf-8')
 return {'rows':len(rows),'passed':passed,'path':str(base/'index.html')}

if __name__=='__main__':print(json.dumps(build(sys.argv[1]),ensure_ascii=False))
